import fs from 'node:fs';import {payloadHash} from '../../execution/ledger.mjs';import {completedTail,entryPolicyTransition} from '../run.mjs';import {replayVariant} from '../compare.mjs';
const dir=process.argv[2],output=process.argv[3];if(!dir||!output)throw Error('tail and new output required');const snapshot=JSON.parse(fs.readFileSync(dir+'/state.json')),{hash,...body}=snapshot;if(hash!==payloadHash(body))throw Error('snapshot');const parent=completedTail(snapshot.continuation.parentDirectory);if(parent.snapshot.hash!==snapshot.continuation.parentSnapshotHash)throw Error('parent');const initial=structuredClone(parent.snapshot.state);if(snapshot.continuation.entryPolicyTransition){const t=entryPolicyTransition(initial,snapshot.continuation.entryPolicyTransition.entryExchangeIds);if(payloadHash(t)!==payloadHash(snapshot.continuation.entryPolicyTransition))throw Error('transition');}
const rows=fs.readFileSync(dir+'/events.jsonl','utf8').split('\n').slice(0,snapshot.sequence).map(JSON.parse);let previous='',sequence=0;for(const row of rows){const{hash:h,...b}=row;if(h!==payloadHash(b)||b.sequence!==++sequence||b.previous!==previous)throw Error('chain');previous=h;}if(previous!==snapshot.lastHash)throw Error('prefix');const events=rows.map(r=>r.event),baseline=replayVariant(initial,events);if(payloadHash(baseline.state)!==payloadHash(snapshot.state))throw Error('baseline parity');
const cases=[['recorded',{}],['retainedPacket',{retainProfitableHedge:true,maximumHedgeOvershoot:initial.policy.quantity}],['executionAge',{inventoryAgeClock:'execution'}],['retainedExecutionAge',{retainProfitableHedge:true,maximumHedgeOvershoot:initial.policy.quantity,inventoryAgeClock:'execution'}],['throughCapacity',{throughFillCapacity:true}],['retainedThroughCapacity',{throughFillCapacity:true,retainProfitableHedge:true,maximumHedgeOvershoot:initial.policy.quantity}]];
const results=[];for(const [name,overrides]of cases){const r=replayVariant(initial,events,overrides);results.push({name,overrides,report:r.report,newFills:r.newFills,lastFresh:r.lastFreshLiquidation,worstFresh:r.worstFreshLiquidation});console.log(JSON.stringify({name,realized:r.report.realized,cash:r.report.cash,owned:r.report.ownedCost,newFills:r.newFills.length,unresolved:r.report.unresolvedOrders,lastFresh:r.lastFreshLiquidation,worstFresh:r.worstFreshLiquidation}));}
fs.writeFileSync(output,JSON.stringify({sourceSnapshotHash:hash,parentSnapshotHash:parent.snapshot.hash,at:snapshot.state.lastAt,sourceEvents:sequence,baselineFinancialParity:true,newPaperCapital:'0.000000',results,contestOrders:0,profitabilityEstablished:false,limitations:['Retrospective inherited-wallet diagnostic, not untouched holdout or verified exchange fills.','Exact captured processing/execution clocks, source gaps, fees, depth and funded liabilities are preserved.','Retaining a full opposite quote permits bounded over-hedging and directional inventory; it does not guarantee both fills.','Original live banks and losses remain unchanged.','Fresh liquidation timestamps must be read with their marks; missing final marks remain null.']},null,2)+'\n',{flag:'wx'});
